CREATE TABLE accounts (
	id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
	email VARCHAR(190) NOT NULL,
	bio TEXT,
	status ENUM('open', 'closed') NOT NULL DEFAULT 'open',
	literal_ts VARCHAR(40) NOT NULL DEFAULT 'CURRENT_TIMESTAMP',
	balance DECIMAL(12, 4) NOT NULL DEFAULT 0.0000,
	email_lower VARCHAR(190) GENERATED ALWAYS AS (LOWER(email)) VIRTUAL,
	display_tag VARCHAR(220) GENERATED ALWAYS AS (CONCAT(email, ':', 'v1')) STORED,
	created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
	reviewed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
	note VARCHAR(100) COMMENT 'owner''s note',
	UNIQUE KEY uk_email (email),
	KEY idx_bio_prefix (bio(32))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='customer accounts';

CREATE TABLE orders (
	id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
	account_id BIGINT NOT NULL,
	total INT NOT NULL,
	KEY idx_account (account_id),
	CONSTRAINT fk_orders_account FOREIGN KEY (account_id) REFERENCES accounts (id) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE p_range (id INT, sold DATE) PARTITION BY RANGE (YEAR(sold)) (PARTITION p2020 VALUES LESS THAN (2021), PARTITION p_max VALUES LESS THAN MAXVALUE);

CREATE TABLE p_range_cols (a INT, b VARCHAR(10)) PARTITION BY RANGE COLUMNS (a, b) (PARTITION p0 VALUES LESS THAN (10, 'm'), PARTITION p1 VALUES LESS THAN (MAXVALUE, MAXVALUE));

CREATE TABLE p_list (a INT) PARTITION BY LIST (a) (PARTITION p_low VALUES IN (1, 2), PARTITION p_rest VALUES IN (DEFAULT));

CREATE TABLE p_list_cols (a INT, b CHAR(2)) PARTITION BY LIST COLUMNS (a, b) (PARTITION p0 VALUES IN ((1, 'a'), (2, 'b')), PARTITION p1 VALUES IN ((3, 'c')));

CREATE TABLE p_hash (a INT) PARTITION BY HASH (a) PARTITIONS 3;

CREATE TABLE p_key (a INT PRIMARY KEY, b INT) PARTITION BY KEY () PARTITIONS 2;

CREATE TABLE p_sub (a INT, b INT) PARTITION BY RANGE (a) SUBPARTITION BY HASH (b) SUBPARTITIONS 2 (PARTITION p0 VALUES LESS THAN (10), PARTITION p1 VALUES LESS THAN (20));

CREATE TABLE p_sub_named (a INT, b INT) PARTITION BY LIST (a) SUBPARTITION BY RANGE (b) (PARTITION p0 VALUES IN (1) (SUBPARTITION s0 VALUES LESS THAN (5), SUBPARTITION s1 VALUES LESS THAN MAXVALUE), PARTITION p1 VALUES IN (2) (SUBPARTITION s2 VALUES LESS THAN MAXVALUE));

CREATE TABLE p_auto (a INT PRIMARY KEY) PARTITION BY RANGE () SIZE ('128MB');

CREATE EXTERNAL TABLE ext_feed (c1 INT, c2 VARCHAR(10) COMMENT 'owner''s note') LOCATION = '/tmp' PATTERN = '.*[.]csv' AUTO_REFRESH = IMMEDIATE FORMAT = (TYPE = 'CSV');

CREATE MATERIALIZED VIEW mv_accounts COMMENT 'owners'' materialized accounts' AS SELECT id, email FROM accounts;

CREATE INDEX idx_mv_email ON mv_accounts (email);

CREATE VIEW v_open_accounts AS
	SELECT id AS acct_id, email AS acct_email FROM accounts WHERE status = 'open';

CREATE VIEW v_named_cols (`renamed_id`) AS SELECT id FROM accounts;

CREATE VIEW v_named_cols_ref AS
	SELECT renamed_id FROM v_named_cols;

CREATE FUNCTION fn_format_tag(p_prefix VARCHAR(16) CHARSET utf8mb4, p_id BIGINT)
RETURNS VARCHAR(64) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
DETERMINISTIC
NO SQL
COMMENT 'formats a tag'
BEGIN
	RETURN CONCAT(p_prefix, '-', p_id);
END;

CREATE PROCEDURE sp_touch_order(IN p_id BIGINT, OUT p_total INT)
COMMENT 'reads an order''s total from C:\\orders'
BEGIN
	SELECT total INTO p_total FROM orders WHERE id = p_id;
END;

SET SESSION sql_mode = 'NO_BACKSLASH_ESCAPES,STRICT_ALL_TABLES,NO_ZERO_IN_DATE,NO_AUTO_CREATE_USER'; CREATE FUNCTION fn_escaped(p VARCHAR(16)) RETURNS VARCHAR(32) CHARSET utf8mb4 DETERMINISTIC NO SQL COMMENT 'it''s C:\\path' RETURN CONCAT(p, '-escaped'); SET SESSION sql_mode = DEFAULT;

CREATE TRIGGER trg_orders_bi BEFORE INSERT ON orders FOR EACH ROW BEGIN IF NEW.total < 0 THEN SET NEW.total = 0; END IF; END;

CREATE EVENT ev_daily_check ON SCHEDULE EVERY 1 DAY STARTS '2030-01-01 00:00:00' DISABLE DO DELETE FROM orders WHERE total < 0;

CREATE EVENT ev_once ON SCHEDULE AT '2030-06-01 12:00:00' ON COMPLETION PRESERVE ENABLE COMMENT 'owner''s \\new once' DO DELETE FROM orders;

CREATE VIEW v_mv_emails AS SELECT email FROM mv_accounts;

CREATE MATERIALIZED VIEW mv_open_accounts AS SELECT acct_id FROM v_open_accounts;
